-- Historical DATA only, not OMO source admission or current trading authority.
-- Prerequisites: CB custody, FX history owner and existing Finance/Social/FX/
-- Captain source catalogs. No operational role gains table SELECT/membership.
begin;
do $$begin
 if not exists(select 1 from pg_roles where rolname='world_v2_day_one_fx_history_owner'and not rolcanlogin and not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolreplication)then raise exception 'CB_OMO_HISTORY_EXISTING_OWNER_REQUIRED'using errcode='42501';end if;
end;$$;
grant create on schema world_v2 to world_v2_day_one_fx_history_owner;
grant select on world_v2.central_bank_omo_adoption,world_v2.central_bank_omo_original,world_v2.central_bank_omo_quote,world_v2.central_bank_omo_revocation to world_v2_day_one_fx_history_owner;
grant update(adoption_ref)on world_v2.central_bank_omo_adoption to world_v2_day_one_fx_history_owner;
grant select on world_v2.world_head,world_v2.opening_seed,world_v2.runtime_opening_admission,world_v2.runtime_admission_publication_permit,world_v2.runtime_admission_publication_revocation,world_v2.authoritative_event,world_v2.command_submission,world_v2.command_receipt,world_v2.financial_posting_batch,world_v2.inventory_posting to world_v2_day_one_fx_history_owner;
grant update(world_version)on world_v2.world_head to world_v2_day_one_fx_history_owner;
grant update(seed_id)on world_v2.runtime_opening_admission to world_v2_day_one_fx_history_owner;
grant update(authorization_id)on world_v2.runtime_admission_publication_permit to world_v2_day_one_fx_history_owner;
grant select on world_v2.social_operating_source_registration,world_v2.social_operating_source_revocation,world_v2.finance_budget_policy_original,world_v2.finance_budget_policy_revocation,world_v2.postwar_day_one_fx_source_original,world_v2.postwar_day_one_fx_source_revocation,world_v2.postwar_day_one_fx_quote_original,world_v2.postwar_day_one_fx_quote_revocation,world_v2.captain_operating_source_adoption,world_v2.captain_operating_source_revocation,world_v2.captain_source_publication_registry to world_v2_day_one_fx_history_owner;
grant update(registration_ref)on world_v2.social_operating_source_registration,world_v2.postwar_day_one_fx_source_original to world_v2_day_one_fx_history_owner;
grant update(policy_ref)on world_v2.finance_budget_policy_original to world_v2_day_one_fx_history_owner;
grant update(adoption_ref)on world_v2.captain_operating_source_adoption to world_v2_day_one_fx_history_owner;
do $$declare t text;begin
 foreach t in array array['world_head','opening_seed','runtime_opening_admission','authoritative_event','command_submission','command_receipt','financial_posting_batch','inventory_posting','social_operating_source_registration','finance_budget_policy_original','postwar_day_one_fx_source_original','postwar_day_one_fx_quote_original','captain_operating_source_adoption','captain_source_publication_registry']loop
 execute format('create policy cb_omo_history_read on world_v2.%I for select to world_v2_day_one_fx_history_owner using(current_user=''world_v2_day_one_fx_history_owner''and world_id=current_setting(''econmind.fx_history_world'',true))',t);
 execute format('create policy cb_omo_history_fence on world_v2.%I as restrictive for select to world_v2_day_one_fx_history_owner using(current_user=''world_v2_day_one_fx_history_owner''and world_id=current_setting(''econmind.fx_history_world'',true))',t);
 end loop;
 foreach t in array array['world_head','runtime_opening_admission','social_operating_source_registration','finance_budget_policy_original','postwar_day_one_fx_source_original','captain_operating_source_adoption']loop
 execute format('create policy cb_omo_history_lock on world_v2.%I for update to world_v2_day_one_fx_history_owner using(current_user=''world_v2_day_one_fx_history_owner''and world_id=current_setting(''econmind.fx_history_world'',true))with check(false)',t);
 end loop;
end;$$;
create function world_v2.read_central_bank_omo_committed_originals(p_world text,p_host_country text,p_office text,p_seed text,p_admission text,p_version text,p_sequence text)
returns table(world_version text,event_sequence text,seed_fingerprint text,admission_ref text,originals jsonb)
language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;required name;h world_v2.world_head%rowtype;a world_v2.runtime_opening_admission%rowtype;permit world_v2.runtime_admission_publication_permit%rowtype;
 host text;origin world_v2.central_bank_omo_adoption%rowtype;stored world_v2.central_bank_omo_original%rowtype;packets jsonb:='[]'::jsonb;quotes jsonb;refs jsonb;n bigint;bytes bigint:=0;parties bigint;begin
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 required:=case p_office when 'FINANCE'then 'world_v2_finance_budget_source_reader'when 'SOCIAL'then 'world_v2_social_source_reader'when 'TREASURY_FX'then 'world_v2_day_one_fx_source_reader'when 'CAPTAIN'then 'world_v2_captain_source_reader'when 'CB_OMO'then 'world_v2_cb_omo_source_reader'else null end;
 if required is null or to_regrole(required)is null or not pg_has_role(effective,required,'MEMBER')or exists(select 1 from pg_roles r where r.rolname=effective and(r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb or r.rolreplication))or exists(select 1 from pg_roles r where r.rolname in('world_v2_day_one_fx_history_owner','world_v2_cb_omo_source_owner','world_v2_cb_omo_source_publisher','world_v2_finance_budget_source_owner','world_v2_finance_budget_source_publisher','world_v2_social_source_owner','world_v2_social_source_publisher','world_v2_day_one_fx_source_owner','world_v2_day_one_fx_source_publisher','world_v2_captain_source_owner')and pg_has_role(effective,r.oid,'MEMBER'))then raise exception 'CB_OMO_HISTORY_FIXED_HOST_READER_REQUIRED'using errcode='42501';end if;
 if p_world is null or p_host_country is null or p_world!~'^[A-Z][A-Z0-9]*([_-][A-Z0-9]+)*$'or p_host_country!~'^[A-Z][A-Z0-9]*([_-][A-Z0-9]+)*$'or p_version is null or p_sequence is null or p_version!~'^(0|[1-9][0-9]*)$'or p_sequence!~'^(0|[1-9][0-9]*)$'then raise exception 'CB_OMO_HISTORY_EXACT_SCOPE_REQUIRED'using errcode='22023';end if;
 perform set_config('econmind.fx_history_world',p_world,true);
 select * into h from world_v2.world_head x where x.world_id=p_world for share;
 if not found or h.world_version::text<>p_version or h.event_sequence::text<>p_sequence or h.world_version>256 or h.event_sequence>256 then raise exception 'CB_OMO_HISTORY_EXACT_BOUNDED_HEAD_REQUIRED'using errcode='55000';end if;
 select * into a from world_v2.runtime_opening_admission x where x.world_id=p_world and x.seed_fingerprint=p_seed and x.admission_ref=p_admission for share;
 if not found or not exists(select 1 from world_v2.opening_seed s where s.world_id=p_world and s.seed_id=a.seed_id and s.seed_fingerprint=p_seed and s.replay_binding=a.replay_binding and s.replay_binding::jsonb->>'modelVersion'=a.model_version)then raise exception 'CB_OMO_HISTORY_ACTUAL_IMMUTABLE_ADMISSION_REQUIRED'using errcode='55000';end if;
 select * into permit from world_v2.runtime_admission_publication_permit x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.model_version=a.model_version and x.replay_binding=a.replay_binding and 'ADMISSION_'||upper(x.authorization_sha256)=p_admission and a.admitted_at_real>=x.valid_from and a.admitted_at_real<x.valid_until for share;
 if not found or exists(select 1 from world_v2.runtime_admission_publication_revocation x where x.authorization_id=permit.authorization_id)then raise exception 'CB_OMO_HISTORY_WORLD_ADMISSION_REVOKED'using errcode='55000';end if;
 -- These are current HOST source guards, not delegated Central Bank authority.
 if p_office='FINANCE'then
  select x.policy_ref into host from world_v2.finance_budget_policy_original x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.finance_budget_policy_revocation r where r.policy_ref=x.policy_ref)order by x.policy_ref limit 1 for share;
 elsif p_office='SOCIAL'then
  select x.registration_ref into host from world_v2.social_operating_source_registration x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.social_operating_source_revocation r where r.registration_ref=x.registration_ref)for share;
 elsif p_office='TREASURY_FX'then
  select x.registration_ref into host from world_v2.postwar_day_one_fx_source_original x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.postwar_day_one_fx_source_revocation r where r.registration_ref=x.registration_ref)and exists(select 1 from world_v2.postwar_day_one_fx_quote_original q where q.world_id=p_world and q.country_id=p_host_country and not exists(select 1 from world_v2.postwar_day_one_fx_quote_revocation r where r.world_id=q.world_id and r.country_id=q.country_id and r.quote_ref=q.quote_ref))for share;
 elsif p_office='CAPTAIN'then
  select x.adoption_ref into host from world_v2.captain_operating_source_adoption x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and not exists(select 1 from world_v2.captain_operating_source_revocation r where r.adoption_ref=x.adoption_ref)and exists(select 1 from world_v2.captain_source_publication_registry r where r.adoption_ref=x.adoption_ref and r.world_id=p_world and r.seed_fingerprint=p_seed and r.world_admission_ref=p_admission)for share;
 else
  select x.adoption_ref into host from world_v2.central_bank_omo_adoption x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.central_bank_omo_revocation r where r.adoption_ref=x.adoption_ref and r.resource_ref='SOURCE')and exists(select 1 from world_v2.central_bank_omo_original o where o.adoption_ref=x.adoption_ref)for share;
 end if;
 if not found then raise exception 'CB_OMO_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 -- The entire frame prefix is separately processed by the shared Core replay.
 -- This provider neither classifies foreign frames as no-effect nor drops them.
 if(select count(*)from world_v2.authoritative_event e where e.world_id=p_world)<>h.event_sequence or(select count(*)from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED')<>h.world_version then raise exception 'CB_OMO_HISTORY_COMPLETE_WORLD_FRONTIER_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where c.world_id=p_world and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and((select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1')<>1 or(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id)<>1 or(select count(*)from world_v2.financial_posting_batch b where b.world_id=p_world and b.causation_command_id=c.command_id)<>1 or exists(select 1 from world_v2.inventory_posting i where i.world_id=p_world and i.causation_command_id=c.command_id)))then raise exception 'CB_OMO_HISTORY_COMPLETE_CB_EFFECT_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from world_v2.authoritative_event e where e.world_id=p_world and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and octet_length(e.canonical_payload)>65536)then raise exception 'CB_OMO_HISTORY_EVENT_CAPACITY_EXCEEDED'using errcode='54000';end if;
 select count(distinct c.country_id)into parties from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where c.world_id=p_world and c.command_type='CORE_CENTRAL_BANK_OMO_V1';
 if parties>70 then raise exception 'CB_OMO_HISTORY_COUNTRY_CAPACITY_EXCEEDED'using errcode='54000';end if;
 for origin in select x.* from world_v2.central_bank_omo_adoption x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and exists(select 1 from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where c.world_id=p_world and c.country_id=x.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1')order by x.country_id for share loop
  -- Revoked CB originals/quotes still explain historical COMMITTED payments.
  -- The adopted parent is held FOR SHARE. Every child INSERT takes its
  -- conflicting FOR UPDATE lock, and child mutation/truncation is forbidden.
  -- No UPDATE grant on immutable original bytes is needed for this read.
  select * into stored from world_v2.central_bank_omo_original x where x.adoption_ref=origin.adoption_ref;
  if not found or stored.original_sha256<>origin.original_sha256 then raise exception 'CB_OMO_HISTORY_REGISTERED_ORIGIN_REQUIRED'using errcode='55000';end if;
  if exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and(e.canonical_payload::jsonb#>>'{trace,snapshot,lineageRef}'is distinct from origin.adoption_ref or e.canonical_payload::jsonb#>>'{trace,snapshot,snapshotRef}'is distinct from origin.source_ref))then raise exception 'CB_OMO_HISTORY_RECORDED_ADOPTION_DIFFERS'using errcode='55000';end if;
  select count(*),coalesce(sum(octet_length(q.quote_text)),0)into n,bytes from world_v2.central_bank_omo_quote q where q.adoption_ref=origin.adoption_ref and exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and e.canonical_payload::jsonb#>>'{source,quote,quoteRef}'=q.quote_ref);
  if n>256 or bytes+octet_length(stored.original_text)>1048576 then raise exception 'CB_OMO_HISTORY_ORIGIN_CAPACITY_EXCEEDED'using errcode='54000';end if;
  select coalesce(jsonb_agg(jsonb_build_object('quote_text',q.quote_text,'quote_sha256',q.quote_sha256)order by q.quote_ref),'[]'::jsonb)into quotes from world_v2.central_bank_omo_quote q where q.adoption_ref=origin.adoption_ref and exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and e.canonical_payload::jsonb#>>'{source,quote,quoteRef}'=q.quote_ref);
  select coalesce(jsonb_agg(jsonb_build_object('command_id',c.command_id,'command_fingerprint',c.command_fingerprint,'event_id',e.event_id,'event_fingerprint',e.event_fingerprint,'transition_id',r.transition_id,'financial_batch_fingerprint',b.batch_fingerprint)order by e.event_sequence),'[]'::jsonb)into refs from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'join world_v2.authoritative_event e on e.world_id=c.world_id and e.causation_command_id=c.command_id and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'join world_v2.financial_posting_batch b on b.world_id=c.world_id and b.causation_command_id=c.command_id where c.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1';
  packets:=packets||jsonb_build_array(jsonb_build_object('country_id',origin.country_id,'adoption_ref',origin.adoption_ref,'source_class',origin.source_class,'source_ref',origin.source_ref,'source_revision',origin.source_revision,'admission_revision',origin.admission_revision,'original_text',stored.original_text,'original_sha256',stored.original_sha256,'quotes',quotes,'frames',refs));
  if octet_length(packets::text)>1048576 then raise exception 'CB_OMO_HISTORY_TOTAL_CAPACITY_EXCEEDED'using errcode='54000';end if;
 end loop;
 if jsonb_array_length(packets)<>parties then raise exception 'CB_OMO_HISTORY_ALL_PARTICIPATING_ORIGINS_REQUIRED'using errcode='55000';end if;
 return query select h.world_version::text,h.event_sequence::text,p_seed,p_admission,packets;
end;$$;
alter function world_v2.read_central_bank_omo_committed_originals(text,text,text,text,text,text,text)owner to world_v2_day_one_fx_history_owner;
revoke all on function world_v2.read_central_bank_omo_committed_originals(text,text,text,text,text,text,text)from public;
grant execute on function world_v2.read_central_bank_omo_committed_originals(text,text,text,text,text,text,text)to world_v2_finance_budget_source_reader,world_v2_social_source_reader,world_v2_day_one_fx_source_reader,world_v2_captain_source_reader,world_v2_cb_omo_source_reader;
revoke create on schema world_v2 from world_v2_day_one_fx_history_owner;
commit;
